ALTER TABLE public.songs ADD COLUMN capo integer CHECK (capo BETWEEN 0 AND 12), ADD COLUMN your_capo integer CHECK (your_capo BETWEEN 0 AND 12); COMMENT ON COLUMN public.songs.capo IS 'Original capo for the written chord chart; null falls back to a capo annotation in chords.'; COMMENT ON COLUMN public.songs.your_capo IS 'Personal performance capo override; null uses the original capo.';